// Fast LUT accessors (no bounds check — mask to table size)
static inline int16_t pcm_sin_i16(uint32_t phase_u32) {
    return pcm_sin_q15[(phase_u32 >> 24) & (PCM_UNIT_CIRCLE_N - 1)];
}
static inline int16_t pcm_cos_i16(uint32_t phase_u32) {
    return pcm_cos_q15[(phase_u32 >> 24) & (PCM_UNIT_CIRCLE_N - 1)];
}
static inline int16_t pcm_tan_i16(uint32_t phase_u32) {
    return pcm_tan_q15[(phase_u32 >> 24) & (PCM_UNIT_CIRCLE_N - 1)];
}

// Linear-interpolated sin (uses top 8 bits index + next 8 bits frac)
static inline int16_t pcm_sin_i16_lerp(uint32_t phase_u32) {
    uint32_t i = (phase_u32 >> 24) & (PCM_UNIT_CIRCLE_N - 1);
    uint32_t j = (i + 1) & (PCM_UNIT_CIRCLE_N - 1);
    int32_t a = pcm_sin_q15[i];
    int32_t b = pcm_sin_q15[j];
    int32_t f = (phase_u32 >> 16) & 0xFF;  // 0..255
    return (int16_t)(a + (((b - a) * f) >> 8));
}
static inline int16_t pcm_cos_i16_lerp(uint32_t phase_u32) {
    uint32_t i = (phase_u32 >> 24) & (PCM_UNIT_CIRCLE_N - 1);
    uint32_t j = (i + 1) & (PCM_UNIT_CIRCLE_N - 1);
    int32_t a = pcm_cos_q15[i];
    int32_t b = pcm_cos_q15[j];
    int32_t f = (phase_u32 >> 16) & 0xFF;
    return (int16_t)(a + (((b - a) * f) >> 8));
}
